const DISPOSABLE = ["mailinator.com","guerrillamail.com","tempmail.com","10minutemail.com","throwawaymail.com","yopmail.com","trashmail.com","getnada.com"];
const lead = $input.item.json;

function isValidPhone(raw) {
  const digits = (raw || "").replace(/\D/g, "");
  return digits.length >= 7 && digits.length <= 15;
}
function isDisposable(raw) {
  if (!raw || !raw.includes("@")) return !!raw;
  return DISPOSABLE.includes(raw.trim().toLowerCase().split("@").pop());
}

const flags = [];
if (!isValidPhone(lead["Phone"])) flags.push("invalid_contact");
if (isDisposable(lead["Email"]) && !flags.includes("invalid_contact")) flags.push("invalid_contact");

const missing = ["Budget","Timeline","Financing","Preferred area/s"].filter(f => !String(lead[f] || "").trim());
if (missing.length) flags.push("incomplete_submission:" + missing.join(","));

return { json: { ...lead, valid: flags.length === 0, flags } };

const FINANCING = {"Cash buyer":30,"Pre-approved mortgage":25,"Needs financing, not yet applied":12,"Not sure / no answer":0};
const TIMELINE = {"Immediately / within 30 days":25,"1\u20133 months":18,"3\u20136 months":8,"Just researching / no timeline":0};
const AREA_TIER = {"Active Listing":20,"General Coverage":10};

const lead = $input.item.json;
const reference = $('Read Reference Data').all().map(i => i.json);
const ref = reference.find(r => (r["Area"] || "").trim() === (lead["Preferred area/s"] || "").trim());

function parseNumber(raw) {
  const m = String(raw || "").match(/([\d,]*\.?\d+)\s*(k|m)?/i);
  if (!m) return null;
  let v = parseFloat(m[1].replace(/,/g, ""));
  if (/k/i.test(m[2])) v *= 1000;
  if (/m/i.test(m[2])) v *= 1000000;
  return v;
}

const financingScore = FINANCING[lead["Financing"]] || 0;
const timelineScore = TIMELINE[lead["Timeline"]] || 0;
const areaScore = ref ? (AREA_TIER[ref["Tier"]] || 0) : 0;

let budgetScore = 0;
const budget = parseNumber(lead["Budget"]);
if (budget !== null && ref && ref["Typical Price"]) {
  const typical = parseFloat(ref["Typical Price"]);
  const pctDiff = Math.abs(budget - typical) / typical;
  budgetScore = pctDiff <= 0.10 ? 25 : pctDiff <= 0.25 ? 12 : 0;
}

const total = financingScore + timelineScore + budgetScore + areaScore;
const label = total >= 80 ? "hot" : total >= 50 ? "warm" : "cold";

return { json: { ...lead, financingScore, timelineScore, budgetScore, areaScore, total, label } };
